238	     7	interface ProfileContextValue {
239	     8	  name: string | null;
240	     9	  setName: (name: string) => void;
241	    10	}
242	    11	
243	    12	const ProfileContext = createContext<ProfileContextValue>({
244	    13	  name: null,
245	    14	  setName: () => {},
246	    15	});
247	    16	
248	    17	interface ProfileProviderProps {
249	    18	  children: ReactNode;
250	    19	  initialName: string | null;
251	    20	}
252	    21	
253	    22	export function ProfileProvider({ children, initialName }: ProfileProviderProps) {
254	    23	  const [name, setNameState] = useState<string | null>(initialName);
255	    24	
256	    25	  const debouncedPersist = useDebouncedCallback((next: string) => {
257	    26	    void persistUserName(next).catch((error) => {
258	    27	      reportError("profile:persistName", error);
259	    28	    });
260	    29	  }, 400);
261	    30	
262	    31	  const setName = useCallback(
263	    32	    (next: string) => {
264	    33	      setNameState(next || null);
265	    34	      debouncedPersist(next);
266	    35	    },
267	    36	    [debouncedPersist]
268	    37	  );
269	    38	
270	    39	  const value = useMemo(() => ({ name, setName }), [name, setName]);
271	    40	
272	    41	  return <ProfileContext.Provider value={value}>{children}</ProfileContext.Provider>;
273	    42	}
274	    43	
275	    44	export function useProfile() {
276	    45	  return useContext(ProfileContext);
277	    46	}
